from typing import List

def longestCommonSubpath(n: int, paths: List[List[int]]) -> int:
    # Helper function to check if there is a common subpath of length k
    def check(k):
        B1, M1 = 100_001, 10 ** 11 + 19
        B2, M2 = 100_003, 10 ** 11 + 21

        common = None
        pow1, pow2 = [1], [1]
        for _ in range(k):
            pow1.append((pow1[-1] * B1) % M1)
            pow2.append((pow2[-1] * B2) % M2)

        for idx, path in enumerate(paths):
            hashes = set()
            h1, h2 = 0, 0
            for i, x in enumerate(path):
                h1 = (h1 * B1 + x) % M1
                h2 = (h2 * B2 + x) % M2
                if i >= k:
                    h1 = (h1 - path[i-k]*pow1[k]) % M1
                    h2 = (h2 - path[i-k]*pow2[k]) % M2
                if i >= k - 1:
                    hashes.add((h1, h2))
            if common is None:
                common = hashes
            else:
                common &= hashes
            if not common:
                return False
        return True

    min_len = min(len(path) for path in paths)
    left, right = 0, min_len
    while left < right:
        mid = (left + right + 1) // 2
        if check(mid):
            left = mid
        else:
            right = mid - 1
    return left
